// One folder per run so two runs can never overwrite each other.
const runId = ($json.submittedAt || String(Date.now())).replace(/[^a-zA-Z0-9]/g, '');
const dir = `/tmp/kenburns-${runId}`;

const rawPrompt = ($json['Image Prompt'] || '').trim();
if (!rawPrompt) throw new Error('The Image Prompt field is empty - nothing to generate.');

// Pollinations reads the prompt straight from the URL path, so a few style words
// appended here go a long way for a faceless-video look without any extra node.
const prompt = `${rawPrompt}, cinematic, dark moody lighting, vertical 9:16 composition`;
const imageUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}?width=1080&height=1920&nologo=true`;

const seconds = Number($json['Clip Length (seconds)']) || 5;
const fps = 25;

return {
  ...$json,
  dir,
  prompt,
  imageUrl,
  imagePath: `${dir}/image.jpg`,
  videoPath: `${dir}/clip.mp4`,
  seconds,
  fps,
  zoomFrames: Math.round(seconds * fps),
};

const cmdResult = $json;
const paths = $('Build the image prompt and file paths').item.json;
if (cmdResult.exitCode !== undefined && cmdResult.exitCode !== 0) {
  throw new Error('FFmpeg failed: ' + (cmdResult.stderr || '').slice(-500));
}
return { json: { videoPath: paths.videoPath, imagePath: paths.imagePath, prompt: paths.prompt, seconds: paths.seconds } };
